SHEET_CSV_URL = "YOUR_GOOGLE_SHEETS_CSV_URL_HERE"

// ── Data: live sheet with local fallback ──────────────────
data = {
  if (SHEET_CSV_URL && SHEET_CSV_URL !== "YOUR_GOOGLE_SHEETS_CSV_URL_HERE") {
    try {
      const resp = await fetch(SHEET_CSV_URL)
      const text = await resp.text()
      return d3.csvParse(text, d3.autoType)
    } catch (e) {
      console.warn("Live sheet unreachable, using local fallback:", e)
    }
  }
  return FileAttachment("data/models.csv").csv({ typed: true })
}

// Live sheet already contains only verified entries;
// local CSV needs filtering
verified = SHEET_CSV_URL !== "YOUR_GOOGLE_SHEETS_CSV_URL_HERE"
  ? data
  : data.filter(d =&gt; d.status === "verified")























n          = verified.length
n_derived  = verified.filter(d =&gt; d.mechanism_derived === "Yes").length
n_cross    = verified.filter(d =&gt; d.cross_arch_validation === "Yes").length
n_jitai    = verified.filter(d =&gt; d.jitai_derived === "Yes").length

pct = (n, total) =&gt; total &gt; 0 ? Math.round(n / total * 100) : 0

html`&lt;div class="stat-grid"&gt;
  &lt;div class="stat-card"&gt;
    &lt;div class="stat-number"&gt;${n}&lt;/div&gt;
    &lt;div class="stat-label"&gt;Studies indexed&lt;/div&gt;
  &lt;/div&gt;
  &lt;div class="stat-card"&gt;
    &lt;div class="stat-number"&gt;${n_derived}&lt;/div&gt;
    &lt;div class="stat-label"&gt;Mechanism-derived architecture&lt;/div&gt;
  &lt;/div&gt;
  &lt;div class="stat-card"&gt;
    &lt;div class="stat-number"&gt;${n_cross}&lt;/div&gt;
    &lt;div class="stat-label"&gt;Cross-arch. validation&lt;/div&gt;
  &lt;/div&gt;
  &lt;div class="stat-card"&gt;
    &lt;div class="stat-number"&gt;${n_jitai}&lt;/div&gt;
    &lt;div class="stat-label"&gt;JITAI derived&lt;/div&gt;
  &lt;/div&gt;
&lt;/div&gt;`













































Filter

theory_opts = ["All theory groups", ...new Set(verified.map(d =&gt; d.theory_group))].sort()
arch_opts   = ["All architectures",  ...new Set(verified.map(d =&gt; d.architecture))].sort()
deriv_opts  = ["All", "Yes", "Partial", "No"]

viewof theory_filter = Inputs.select(theory_opts, { label: "Theory group" })
viewof arch_filter   = Inputs.select(arch_opts,   { label: "Architecture" })
viewof deriv_filter  = Inputs.select(deriv_opts,  { label: "Mechanism-derived?" })
viewof search_text   = Inputs.search(verified, {
  placeholder: "Search authors, behaviors, theories…",
  label: "Search"
})



















































filtered = {
  let result = search_text
  if (theory_filter !== "All theory groups")
    result = result.filter(d =&gt; d.theory_group === theory_filter)
  if (arch_filter !== "All architectures")
    result = result.filter(d =&gt; d.architecture === arch_filter)
  if (deriv_filter !== "All")
    result = result.filter(d =&gt; d.mechanism_derived === deriv_filter)
  return result
}







function badge(val) {
  if (val === "Yes")     return "✓ Yes"
  if (val === "Partial") return "◑ Partial"
  if (val === "No")      return "✗ No"
  return val || "—"
}

Inputs.table(filtered, {
  columns: [
    "author", "year", "behavior",
    "theory_group", "architecture",
    "mechanism_derived", "cross_arch_validation", "jitai_derived"
  ],
  header: {
    author:                "Author(s)",
    year:                  "Year",
    behavior:              "Behavior",
    theory_group:          "Theory group",
    architecture:          "Architecture",
    mechanism_derived:     "Mechanism-derived?",
    cross_arch_validation: "Cross-arch. valid.?",
    jitai_derived:         "JITAI derived?"
  },
  format: {
    author: d =&gt; d,
    year:   d =&gt; d,
    mechanism_derived:     d =&gt; badge(d),
    cross_arch_validation: d =&gt; badge(d),
    jitai_derived:         d =&gt; badge(d)
  },
  width: {
    author:                160,
    year:                   50,
    behavior:              130,
    theory_group:          180,
    architecture:          200,
    mechanism_derived:     110,
    cross_arch_validation: 110,
    jitai_derived:          90
  },
  rows: 20
})















Click any row to expand details below.

viewof selected = Inputs.table(filtered, {
  columns: ["author", "year", "behavior", "theory_group", "architecture",
            "mechanism_derived", "cross_arch_validation", "jitai_derived"],
  value: null,
  multiple: false
})







{
  if (!selected || selected.length === 0) return md``
  const d = Array.isArray(selected) ? selected[0] : selected

  const row = (label, val) =&gt;
    val ? `&lt;tr&gt;&lt;th style="width:200px;text-align:left;font-weight:600;padding:4px 8px"&gt;${label}&lt;/th&gt;&lt;td style="padding:4px 8px"&gt;${val}&lt;/td&gt;&lt;/tr&gt;` : ""

  return html`
    &lt;details open style="background:#f8f9fa;border:1px solid #dee2e6;border-radius:6px;padding:1rem;margin-top:1rem"&gt;
      &lt;summary style="font-weight:700;cursor:pointer;font-size:1.05rem"&gt;
        ${d.author} (${d.year}) — ${d.behavior}
      &lt;/summary&gt;
      &lt;table style="margin-top:0.75rem;border-collapse:collapse;width:100%;font-size:0.88rem"&gt;
        ${row("DOI / URL",              d.doi_url ? `&lt;a href="${d.doi_url}" target="_blank"&gt;${d.doi_url}&lt;/a&gt;` : "—")}
        ${row("Behavior category",      d.behavior_category)}
        ${row("Theory (full name)",     d.theory_name)}
        ${row("Theory group",           d.theory_group)}
        ${row("Architecture",           d.architecture)}
        ${row("Mechanism-derived?",     badge(d.mechanism_derived))}
        ${row("Rationale",              d.mechanism_rationale)}
        ${row("Cross-arch. validation?",badge(d.cross_arch_validation))}
        ${row("Validation method",      d.cross_arch_method)}
        ${row("ΔELPD",                  d.delta_elpd ? String(d.delta_elpd) : null)}
        ${row("JITAI derived?",         badge(d.jitai_derived))}
        ${row("JITAI — who?",           d.jitai_who)}
        ${row("JITAI — when?",          d.jitai_when)}
        ${row("Study design",           d.study_design)}
        ${row("N participants",         d.n_participants ? String(d.n_participants) : null)}
        ${row("Study duration (days)",  d.study_duration_days ? String(d.study_duration_days) : null)}
        ${row("EMA prompts/day",        d.ema_assessments_per_day ? String(d.ema_assessments_per_day) : null)}
        ${row("Outcome type",           d.outcome_type)}
        ${row("Notes",                  d.notes)}
      &lt;/table&gt;
    &lt;/details&gt;`
}









Overview charts

arch_counts = {
  const counts = d3.rollups(
    verified, v =&gt; v.length, d =&gt; d.architecture
  ).map(([architecture, count]) =&gt; ({ architecture, count }))
  return counts.sort((a, b) =&gt; b.count - a.count)
}

theory_counts = {
  const counts = d3.rollups(
    verified, v =&gt; v.length, d =&gt; d.theory_group
  ).map(([theory_group, count]) =&gt; ({ theory_group, count }))
  return counts.sort((a, b) =&gt; b.count - a.count)
}















Plot.plot({
  title: "Architecture distribution",
  marks: [
    Plot.barX(arch_counts, {
      x: "count", y: "architecture",
      sort: { y: "-x" },
      fill: "#3498db",
      tip: true
    }),
    Plot.ruleX([0])
  ],
  marginLeft: 220,
  x: { label: "Studies", tickFormat: d =&gt; Number.isInteger(d) ? d : "" },
  y: { label: null }
})
Plot.plot({
  title: "Theory group distribution",
  marks: [
    Plot.barX(theory_counts, {
      x: "count", y: "theory_group",
      sort: { y: "-x" },
      fill: "#2c3e50",
      tip: true
    }),
    Plot.ruleX([0])
  ],
  marginLeft: 220,
  x: { label: "Studies", tickFormat: d =&gt; Number.isInteger(d) ? d : "" },
  y: { label: null }
})



















deriv_counts = {
  const vals = ["Yes", "Partial", "No"]
  const colors = { Yes: "#1a7a4a", Partial: "#b8600a", No: "#b02020" }
  return vals.map(v =&gt; ({
    label: v,
    count: verified.filter(d =&gt; d.mechanism_derived === v).length,
    fill: colors[v]
  }))
}

Plot.plot({
  title: "Mechanism-derived architecture (all studies)",
  marks: [
    Plot.barX(deriv_counts, {
      x: "count", y: "label",
      fill: "fill",
      tip: true
    }),
    Plot.ruleX([0])
  ],
  marginLeft: 80,
  x: { label: "Studies", tickFormat: d =&gt; Number.isInteger(d) ? d : "" },
  y: { label: null }
})
















